scripts.script:
// 遍历所有七维属性，检定结果+1
Object.values(S.stats).forEach(s => {
    if (s.hasOwnProperty('checkMod')) s.checkMod += 1;
});
// 遍历所有技能，检定结果+1
Object.values(S.skills).forEach(s => {
    if (s.hasOwnProperty('checkMod')) s.checkMod += 1;
});

S.combat.speed += 2;
S.combat.hit_waigong += 5;
S.combat.hit_neigong += 5;
S.combat.damages.skill.mod += 5;

S.combat.speed += 3;
S.combat.hit_waigong += 10;
S.combat.hit_neigong += 10;
S.combat.damages.skill.mod += 10;

S.combat.crit_waigong -= 2;
S.combat.crit_neigong -= 2;
S.combat.damages.skill.mod += 5;

S.combat.crit_waigong -= 3;
S.combat.crit_neigong -= 3;
S.combat.damages.skill.mod += 15;

const eff = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuyi");
if (eff) {
    await eff.delete();
    actor.showFloatyText("无意消散", { fill: "#cccccc" });
}

if (args.targets && args.targets.some(t => (t.hpLost > 0 || t.hutiLost > 0))) {
    const eff = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuyi");
    if (eff) {
        await eff.delete();
        actor.showFloatyText("无意消散", { fill: "#cccccc" });
    }
}

// 1. 流失 50 内力
await actor.applyHealing({ amount: -50, type: "mp" });

// 2. 读取本场战斗的 D12 记录池 (防跨场战斗污染)
let records = actor.getFlag("xjzl-system", "xumingRecords") || [];
let recordCombatId = actor.getFlag("xjzl-system", "xumingCombatId");
let currentCombatId = game.combat ? game.combat.id : "none";

if (recordCombatId !== currentCombatId) {
    records =[];
    recordCombatId = currentCombatId;
}

// 3. 投掷 D12
const roll = await new Roll("1d12").evaluate();
if (game.dice3d) game.dice3d.showForRoll(roll, game.user, true);
const result = roll.total;

let isDuplicate = records.includes(result);
if (!isDuplicate) {
    // 没重复：阻止濒死
    records.push(result);
    await actor.setFlag("xjzl-system", "xumingRecords", records);
    await actor.setFlag("xjzl-system", "xumingCombatId", currentCombatId);
    args.preventDying = true;

    const msg = `
    <div class="xjzl-chat-card">
        <div style="padding:5px; border-left:4px solid #f39c12; padding-left:10px;">
            <b>续命秘法 (D12: ${result})</b><br>
            点数未重复！你强行撑住了残躯，<b>免疫濒死状态</b>继续战斗！<br>
            <i style="color:#888; font-size: 0.9em;">(请手动进行残疾检定。已出现点数：${records.join(", ")})</i>
        </div>
    </div>`;
    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });
} else {
    // 重复了：不阻止濒死
    const msg = `
    <div class="xjzl-chat-card">
        <div style="padding:5px; border-left:4px solid #c0392b; padding-left:10px;">
            <b>续命秘法 (D12: ${result})</b><br>
            点数重复！秘法宣告失效，你彻底陷入了濒死！<br>
            <i style="color:#c0392b;">请手动进行残疾检定，并立即进行一次死检。</i>
        </div>
    </div>`;
    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });
}

if (!game.combat) return;
await actor.applyHealing({ amount: 5, type: "hp" });
await actor.applyHealing({ amount: 5, type: "mp" });

if (!game.combat) return;
const hpRatio = S.resources.hp.value / Math.max(1, S.resources.hp.max);
const mpRatio = S.resources.mp.value / Math.max(1, S.resources.mp.max);

if (hpRatio < 0.3 || mpRatio < 0.3) {
    const currentCombatId = game.combat.id;
    const usedFlag = actor.getFlag("xjzl-system", "zizaiHealCombatId");
    if (usedFlag !== currentCombatId) {
        await actor.applyHealing({ amount: 25, type: "hp" });
        await actor.applyHealing({ amount: 25, type: "mp" });
        await actor.setFlag("xjzl-system", "zizaiHealCombatId", currentCombatId);

        const msg = `<div class="xjzl-chat-card"><div style="padding:5px; border-left:4px solid #8e44ad; padding-left:10px;"><b>生机勃勃·绝境：</b><br>气血或内力告急，激发先天真气，一次性恢复 25 点气血与内力！</div></div>`;
        ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });
    }
}

if (!game.combat) return;
await actor.applyHealing({ amount: 10, type: "hp" });
await actor.applyHealing({ amount: 10, type: "mp" });

if (!game.combat) return;
const hpRatio = S.resources.hp.value / Math.max(1, S.resources.hp.max);
const mpRatio = S.resources.mp.value / Math.max(1, S.resources.mp.max);

if (hpRatio < 0.3 || mpRatio < 0.3) {
    const currentCombatId = game.combat.id;
    const usedFlag = actor.getFlag("xjzl-system", "zizaiHealCombatId");
    if (usedFlag !== currentCombatId) {
        await actor.applyHealing({ amount: 50, type: "hp" });
        await actor.applyHealing({ amount: 50, type: "mp" });
        await actor.setFlag("xjzl-system", "zizaiHealCombatId", currentCombatId);

        const msg = `<div class="xjzl-chat-card"><div style="padding:5px; border-left:4px solid #8e44ad; padding-left:10px;"><b>生机勃勃·绝境：</b><br>气血或内力告急，激发先天真气，一次性恢复 50 点气血与内力！</div></div>`;
        ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });
    }
}

if (!game.combat) return;
await actor.applyHealing({ amount: 20, type: "hp" });
await actor.applyHealing({ amount: 20, type: "mp" });

if (!game.combat) return;
const hpRatio = S.resources.hp.value / Math.max(1, S.resources.hp.max);
const mpRatio = S.resources.mp.value / Math.max(1, S.resources.mp.max);

if (hpRatio < 0.3 || mpRatio < 0.3) {
    const currentCombatId = game.combat.id;
    const usedFlag = actor.getFlag("xjzl-system", "zizaiHealCombatId");
    if (usedFlag !== currentCombatId) {
        await actor.applyHealing({ amount: 100, type: "hp" });
        await actor.applyHealing({ amount: 100, type: "mp" });
        await actor.setFlag("xjzl-system", "zizaiHealCombatId", currentCombatId);

        const msg = `<div class="xjzl-chat-card"><div style="padding:5px; border-left:4px solid #8e44ad; padding-left:10px;"><b>生机勃勃·绝境：</b><br>气血或内力告急，激发先天真气，一次性恢复 100 点气血与内力！</div></div>`;
        ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });
    }
}

let t3MaxCount = 0;
// 遍历身上所有内功
for (const item of actor.itemTypes.neigong) {
    if (item.system.tier === 3 && item.system.stage >= 3) {
        t3MaxCount++;
    }
}
const bonus = Math.min(40, t3MaxCount * 10);
if (bonus > 0) {
    S.stats.liliang.mod += bonus;
    S.stats.shenfa.mod += bonus;
    S.stats.tipo.mod += bonus;
    S.stats.neixi.mod += bonus;
    S.stats.qigan.mod += bonus;
    S.stats.shencai.mod += bonus;
  }

if (args.move && args.move.type !== "stance" && args.move.type !== "qi") {
    args.output.damage += 50;
    args.output.bonusDesc.push(`先天真气加成 +50`);
}
